def load_tagged_documents(root: str):
    root_path = Path(root)
    for l in root_path.glob("*/*/*.txt"):
        department = l.parent.parent.name
        clearance = l.parent.name
        yield l.read_text(encoding="utf-8"), {"department": department, "clearance": clearance, "source": l.name}
